    // @ts-expect-error
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.safe_float(inputDict.clone(), Value::Str("strNumber".into()), &[]).as_f64() == ccxt::runtime::parse_float(&Value::Int(3)).as_f64()))));
